import { Component, computed, input } from '@angular/core';
import { HrmTag, HrmTagColor, HrmTagVariant } from '../data-display/hrm-tag';

/** 1 nhãn trong ô: text + màu hue tuỳ chọn. */
export interface HrmTagItem {
  label: string;
  color?: HrmTagColor;
}

/** hrm-tags-cell — ô nhiều nhãn: hiện tối đa `max` nhãn, phần dư gộp thành "+N".
 *  Bọc hrm-tag (size sm) → thừa hưởng 4 kiểu variant + màu hue DS. */
@Component({
  selector: 'hrm-tags-cell',
  imports: [HrmTag],
  template: `
    @for (t of visible(); track $index) {
      <hrm-tag [color]="t.color || 'gray'" [variant]="variant()" size="sm">{{ t.label }}</hrm-tag>
    }
    @if (overflow() > 0) {
      <hrm-tag color="gray" variant="light" size="sm">+{{ overflow() }}</hrm-tag>
    }
  `,
  host: { class: 'hrm-tags-cell' },
  styles: [`
:host { display: inline-flex; align-items: center; gap: 4px; flex-wrap: nowrap; min-width: 0; max-width: 100%; }
/* nz-tag mặc định margin-inline-end 8px → khử để khoảng cách chỉ do gap 4px điều khiển. */
:host ::ng-deep .ant-tag { margin: 0; }
  `],
})
export class HrmTagsCell {
  readonly tags = input<HrmTagItem[]>([]);
  /** Số nhãn tối đa hiện trước khi gộp "+N". */
  readonly max = input(3);
  readonly variant = input<HrmTagVariant>('light');

  protected readonly visible = computed(() => this.tags().slice(0, this.max()));
  protected readonly overflow = computed(() => Math.max(0, this.tags().length - this.max()));
}
